#include <array>
#include <cstdint>
#include <iostream>

class TransitionMatrix {
public:
    std::array<std::array<std::int64_t, 4>, 4> matrix{};

    std::int64_t operator()(int i, int j) const {
        return matrix[i][j];
    }

    std::int64_t& operator()(int i, int j) {
        return matrix[i][j];
    }

    TransitionMatrix operator*(const TransitionMatrix& other) const {
        constexpr std::int64_t modulo = 1000000007LL;
        TransitionMatrix result;

        for (int i = 0; i <= 3; ++i) {
            for (int j = 0; j <= 3; ++j) {
                std::int64_t x = 0;
                for (int k = 0; k <= 3; ++k) {
                    x = (x + (*this)(i, k) * other(k, j)) % modulo;
                }
                result(i, j) = x;
            }
        }
        return result;
    }
};

TransitionMatrix identity_matrix() {
    TransitionMatrix result;
    result(0, 0) = 1;
    result(1, 1) = 1;
    result(2, 2) = 1;
    result(3, 3) = 1;
    return result;
}

TransitionMatrix ant_matrix() {
    TransitionMatrix result;

    for (int i = 0; i <= 3; ++i) {
        for (int j = 0; j <= 3; ++j) {
            result(i, j) = 1;
        }
    }

    result(0, 0) = 0;
    result(1, 1) = 0;
    result(2, 2) = 0;
    result(3, 3) = 0;
    return result;
}

std::int64_t num_paths(int n) {
    auto raise_to = [](auto&& self, const TransitionMatrix& t, int x)
        -> TransitionMatrix {
        if (x == 0) {
            return identity_matrix();
        } else if (x % 2 == 0) {
            TransitionMatrix t_sqr = t * t;
            return self(self, t_sqr, x / 2);
        } else {
            TransitionMatrix t_sqr = t * t;
            return t * self(self, t_sqr, (x - 1) / 2);
        }
    };

    TransitionMatrix t_matrix = ant_matrix();
    TransitionMatrix result = raise_to(raise_to, t_matrix, n);
    return result(0, 0);
}

int main() {
    int n;
    if (std::cin >> n) {
        std::cout << num_paths(n) << '\n';
    }
    return 0;
}

